from pathlib import Path
import base64,gzip,sys

def dec(x): return gzip.decompress(base64.b64decode(x)).decode()
SCANNER=dec("")
SCORE=dec("")
SUPPORT=dec("")
p=Path(sys.argv[1] if len(sys.argv)>1 else "_site/index.html")
s=p.read_text()
a=s.index("async function checkSupport()")
b=s.index("\nfunction showGate",a)
s=s[:a]+SUPPORT+s[b:]
a=s.index("const RULES=[")
b=s.index("async function reposOf",a)
s=s[:a]+SCANNER+"\n"+s[b:]
s=s.replace("rule_id:'UNDOCUMENTED_TRANSACTION_CAPABILITY',severity:'HIGH'","rule_id:'UNDOCUMENTED_TRANSACTION_CAPABILITY',severity:'LOW'")
a=s.index("function score(")
b=s.index("async function audit(",a)
s=s[:a]+SCORE+s[b:]
s=s.replace("SEVERE RISK • SCAM INDICATORS","SEVERE SECURITY RISK • POSSIBLE SCAM INDICATORS")
s=s.replace("ریسک شدید • نشانه‌های اسکم","ریسک امنیتی شدید • نشانه‌های احتمالی اسکم")
p.write_text(s)
